方法 2（最优）：
(1) 直接找出所有元素中的最大值 max 与最小值 min。若当前元素 A[i]<0，则 res[i]=A[i]×min（此时 min 必小于 0，负负得正）；若 A[i]>0，则 res[i]=A[i]×max（此时 max 必大于 0）。
(2) 代码：
void calMulMax(int A[], int res[], int n) {
    int max=A[0], min=A[0];
    for(int i=0;i<n;i++) {  // 找出最大值和最小值
        if(A[i]>=max) max=A[i];
        if(A[i]<=min) min=A[i];
    }
    for(int i=0;i<n;i++) {
        if(A[i]<0) res[i]=A[i]*min;
        else res[i]=A[i]*max;
    }
}
(3) 时间复杂度 O(n)，空间复杂度 O(1)。

semaphore mutexT=1;  // 对铁锹的使用需要互斥访问（甲挖坑、乙填土都用铁锹）
semaphore sk=3;     // 可挖的树坑数量，初值为 3（甲挖树坑当且仅当树坑<3）
semaphore empty=0;  // 可使用的树坑数量（乙需要有空坑才能放树苗）
semaphore water=0;  // 需要浇水的树苗数量（丙需要有已种好的树苗才能浇水）

甲() {
    while(1) {
        wait(sk);       // 申请挖树坑名额
        wait(mutexT);   // 申请铁锹
        挖坑;
        signal(mutexT); // 释放铁锹
        signal(empty);  // 增加一个空坑
    }
}
乙() {
    while(1) {
        wait(empty);    // 等待空坑
        wait(mutexT);   // 申请铁锹（填土需要铁锹）
        入坑并填土;
        signal(mutexT); // 释放铁锹
        signal(sk);     // 释放挖树坑名额
        signal(water);  // 增加需要浇水的树苗
    }
}
丙() {
    while(1) {
        wait(water);    // 等待需要浇水的树苗
        浇水;
    }
}
